import React from 'react';
import withRenderTimeLogging from './withRenderTimeLogging';

// Sample component
class MyComponent extends React.Component {
  render() {
    return <div>Hello, World!</div>;
}

// Wrap MyComponent with withRenderTimeLogging HOC
