function resolveModuleImport(importStatement: string): string {
  const regex = /export {.*} from '(.*)';/;
  const match = importStatement.match(regex);
  if (match && match[1]) {
    const relativePath = match[1];
    // Resolve the relative path to absolute path based on the project's base directory
    const absolutePath = resolveAbsolutePath(relativePath);
    return `Resolved module path: ${absolutePath}`;
