  "./PacksListError": 0,
  "./Utils": 0,
  "./DataHandler": 0,
}
```

### Solution:
```javascript
function processImports(imports) {
  const moduleStars = {};
  for (const importStatement of imports) {
    const moduleName = importStatement.match(/"([^"]+)"/)[1];
