```

### Solution:
```typescript
function extractFileExtension(filePath: string): string {
  const lastDotIndex = filePath.lastIndexOf('.');
  if (lastDotIndex === -1 || lastDotIndex === filePath.length - 1) {
    return '';
  } else {
    return filePath.slice(lastDotIndex + 1);
  }
}
```

