```python
class MessageQueue:
    def __init__(self, maxsize):
        self.maxsize = maxsize
        self.queue = []

    def enqueue(self, message):
        if len(self.queue) < self.maxsize:
            self.queue.append(message)
        else:
            raise ValueError("Queue is full")

