### Solution:
```go
package main

import (
	"database/sql"
	"fmt"
	"log"
	"os"

	_ "github.com/lib/pq"
	"github.com/badoux/checkmail"
	"golang.org/x/crypto/bcrypt"
)

const (
	host     = "localhost"
	port     = 5432
	user     = "your_username"
	password = "your_password"
	dbname   = "your_dbname"
)

func main() {
	dbinfo := fmt.Sprintf("host=%s port=%d user=%s password=%s dbname=%s sslmode=disable",
		host, port, user, password, dbname)

	db, err := sql.Open("postgres", dbinfo)
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	err = db.Ping()
	if err != nil {
		log.Fatal(err)
	}

	// Add a new user to the database
	// Assume user input for email and password
	email := "user@example.com"
	password := "password123"
	err = checkmail.ValidateFormat(email)
	if err != nil {
		log.Fatal("Invalid email format")
	}

	hashedPassword, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		log.Fatal(err)
	}

	_, err = db.Exec("INSERT INTO users (email, password) VALUES ($1, $2)", email, string(hashedPassword))
	if err != nil {
		log.Fatal(err)
	}

	// Authenticate a user
	// Assume user input for email and password
	email = "user@example.com"
	password = "password123"
	var storedPassword string
	err = db.QueryRow("SELECT password FROM users WHERE email = $1", email).Scan(&storedPassword)
	if err != nil {
		log.Fatal("User not found")
	}

	err = bcrypt.CompareHashAndPassword([]byte(storedPassword), []byte(password))
	if err != nil {
		log.Fatal("Invalid password")
	}

	fmt.Println("User authenticated successfully")

	// Update a user's information
	// Assume user input for email and new password
	email = "user@example.com"
	newPassword := "newpassword456"
	hashedNewPassword, err := bcrypt.GenerateFromPassword([]byte(newPassword), bcrypt.DefaultCost)
	if err != nil {
		log.Fatal(err)
	}

	_, err = db.Exec("UPDATE users SET password = $1 WHERE email = $2", string(hashedNewPassword), email)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Println("User information updated successfully")

	// Delete a user from the database
	// Assume user input for email
	email = "user@example.com"
	_, err = db.Exec("DELETE FROM users WHERE email = $1", email)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Println("User deleted successfully")
}
```

