### Problem:
You are tasked with creating a Python program that reads a JSON file containing information about a collection of books and performs various operations on this data. The JSON file contains an array of objects, each representing a book with attributes such as title, author, genre, and publication year. Your program should provide the following functionalities:

1. Load the book data from the provided JSON file.
2. Display the total number of books in the collection.
3. Allow the user to search for a book by its title and display its details if found.
4. Provide the option to add a new book to the collection and update the JSON file accordingly.
5. Calculate and display the average publication year of all the books in the collection.

Your program should have a user-friendly interface, guiding the user through the available options and handling input validation.

### Solution:
```python
import json

def load_books_from_json(file_path):
    with open(file_path, 'r') as file:
        return json.load(file)

def save_books_to_json(file_path, books):
    with open(file_path, 'w') as file:
        json.dump(books, file, indent=4)

def display_total_books(books):
    print(f"Total number of books in the collection: {len(books)}")

def search_book_by_title(books, title):
    for book in books:
        if book['title'].lower() == title.lower():
            print(f"Book found: {book}")
            return
    print(f"No book with the title '{title}' found.")

def add_new_book(books, new_book):
    books.append(new_book)
    return books

def calculate_average_publication_year(books):
    publication_years = [book['publication_year'] for book in books]
    return sum(publication_years) / len(publication_years)

def main():
    file_path = 'books.json'
    books = load_books_from_json(file_path)

    while True:
        print("\nOptions:")
        print("1. Display total number of books")
        print("2. Search for a book by title")
        print("3. Add a new book to the collection")
        print("4. Calculate average publication year of all books")
        print("5. Exit")

        choice = input("Enter your choice: ")

        if choice == '1':
            display_total_books(books)
        elif choice == '2':
            title = input("Enter the title of the book: ")
            search_book_by_title(books, title)
        elif choice == '3':
            new_book = {
                "title": input("Enter the title of the new book: "),
                "author": input("Enter the author of the new book: "),
                "genre": input("Enter the genre of the new book: "),
                "publication_year": int(input("Enter the publication year of the new book: "))
            }
            books = add_new_book(books, new_book)
            save_books_to_json(file_path, books)
            print("New book added successfully.")
        elif choice == '4':
            average_year = calculate_average_publication_year(books)
            print(f"Average publication year of all books: {average_year:.2f}")
        elif choice == '5':
            print("Exiting the program.")
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
```

