### Solution:
```python
from exasol_data_science_utils_python.utils.repr_generation_for_object import generate_repr_for_object
import math

class GeometricShape:
    def __init__(self):
        pass

    def calculate_area(self):
        raise NotImplementedError("Subclasses must implement calculate_area method")

    def calculate_perimeter(self):
        raise NotImplementedError("Subclasses must implement calculate_perimeter method")

    def __repr__(self):
        return generate_repr_for_object(self, additional_attributes={})

class Rectangle(GeometricShape):
    def __init__(self, length, width):
        super().__init__()
        self.length = length
        self.width = width

    def calculate_area(self):
        return self.length * self.width

    def calculate_perimeter(self):
        return 2 * (self.length + self.width)

