// Import the necessary modules and types for the solution
use proptest::prelude::*;
use ropey::Rope;
use ropey::str_utils::AbsoluteCharOffset;

// Implementation of the arb_absolute_char_offset generator
fn arb_absolute_char_offset(max_len: usize) -> impl Strategy<Value = AbsoluteCharOffset> {
    0..max_len.prop_map(AbsoluteCharOffset)
}

// Implementation of the arb_rope_and_offset generator
fn arb_rope_and_offset() -> impl Strategy<Value = (Rope, AbsoluteCharOffset)> {
    (".*".prop_map(Rope::from_str), 0..=r!(s).len_chars()).prop_map(|(rope, offset)| (rope, AbsoluteCharOffset(offset)))
}

