```typescript
import * as fs from 'fs';
import * as util from 'util';
import * as path from 'path';
import * as https from 'https';

const writeFileAsync = util.promisify(fs.writeFile);
const renameAsync = util.promisify(fs.rename);
const symlinkAsync = util.promisify(fs.symlink);
const unlinkAsync = util.promisify(fs.unlink);

class FileManagerImpl implements FileManager {
  constructor(
    public tmpDownloadPath: string,
    public installDir: string,
    public symlinkPath: string
  ) {}

  async downloadFile(url: string): Promise<void> {
    const file = fs.createWriteStream(this.tmpDownloadPath);
    return new Promise<void>((resolve, reject) => {
      https.get(url, (response) => {
        response.pipe(file);
        file.on('finish', () => {
          file.close();
          resolve();
        });
      }).on('error', (err) => {
        fs.unlink(this.tmpDownloadPath, () => reject(err));
      });
    });
  }

  async installFile(fileName: string): Promise<void> {
    const sourcePath = path.join(this.tmpDownloadPath, fileName);
    const targetPath = path.join(this.installDir, fileName);
    return renameAsync(sourcePath, targetPath);
  }

  async createSymlink(): Promise<void> {
    return symlinkAsync(this.installDir, this.symlinkPath, 'junction');
  }
}
```

