### Solution:
```javascript
function resolveModuleImports(importStatements) {
  const resolvedExports = {};

  const resolveModule = (moduleName) => {
    const moduleExports = require(moduleName); // Assuming a Node.js environment for simplicity
    Object.assign(resolvedExports, moduleExports);
  };

  importStatements.forEach((importStatement) => {
    const moduleName = importStatement.match(/'([^']+)'/)[1];
    resolveModule(moduleName);
  });

  return resolvedExports;
}

// Example usage
const importStatements = [
  "export * from './HiveNode';",
  "export * from './HiveUtils';",
  "export * from './HiveConstants';"
];
