│   └── index.ts
├── config/
│   └── index.ts
├── tmf-appointment-models/
│   └── index.ts
├── services/
│   └── index.ts
└── tmf-appointment.module.ts
```

You need to create a script that generates an `index.ts` file at the root level, which re-exports all the modules from the subdirectories. The generated `index.ts` file should look like this:
```
