export * from './config/index';
export * from './tmf-appointment-models/index';
export * from './services/index';
export * from './tmf-appointment.module';
```

Write a TypeScript function `generateRootIndex` that takes the project directory path as input and dynamically generates the content for the `index.ts` file. The function should read the `index.ts` files from the subdirectories and construct the re-export statements based on the modules present in each `index.ts` file. The generated content should be written to a new `index.ts` file at the root level of the project directory.

Function Signature: `function generateRootIndex(projectPath: string): void`

Example:
Input:
```
generateRootIndex('path/to/project');
```

Output:
A new `index.ts` file is created at the root level of the project directory with the re-export statements as shown above.

### Solution:
```typescript
import fs from 'fs';
import path from 'path';

function generateRootIndex(projectPath: string): void {
  const rootIndexPath = path.join(projectPath, 'index.ts');
  let indexContent = '';

  const subdirectories = fs.readdirSync(projectPath, { withFileTypes: true })
    .filter(dirent => dirent.isDirectory())
    .map(dirent => dirent.name);

  subdirectories.forEach(subdir => {
    const indexPath = path.join(projectPath, subdir, 'index.ts');
    if (fs.existsSync(indexPath)) {
      const subIndexContent = fs.readFileSync(indexPath, 'utf-8');
      indexContent += subIndexContent + '\n';
    }
  });

  fs.writeFileSync(rootIndexPath, indexContent);
}

// Example usage
generateRootIndex('path/to/project');
```

This solution defines the `generateRootIndex` function, which reads the subdirectories of the project directory, reads the content of each `index.ts` file in the subdirectories, and concatenates the content to form the re-export statements. Finally, it writes the concatenated content to a new `index.ts` file at the root level of the project directory.

