### Solution:
```python
import subprocess

class SystemServiceManager:
    @staticmethod
    def execute_command(command):
        try:
            result = subprocess.run(command, shell=True, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
            return result.stdout.strip()
        except subprocess.CalledProcessError as e:
            return f"Error: {e.stderr.strip()}"

    @staticmethod
    def start_service(service_name):
        return SystemServiceManager.execute_command(f"sudo systemctl start {service_name}")

    @staticmethod
    def stop_service(service_name):
        return SystemServiceManager.execute_command(f"sudo systemctl stop {service_name}")

    @staticmethod
    def restart_service(service_name):
        return SystemServiceManager.execute_command(f"sudo systemctl restart {service_name}")

    @staticmethod
    def check_service_status(service_name):
        return SystemServiceManager.execute_command(f"sudo systemctl status {service_name}")

# Demonstrate usage
if __name__ == "__main__":
    service_manager = SystemServiceManager()
    print(service_manager.start_service("consul"))
    print(service_manager.check_service_status("consul"))
    print(service_manager.restart_service("consul"))
    print(service_manager.stop_service("consul"))
```

