### Solution:
```swift
import UIKit

class TipCalculatorViewController: UIViewController {

    @IBOutlet weak var tipControl: UISegmentedControl!
    @IBOutlet weak var billAmountTextField: UITextField!
    @IBOutlet weak var tipAmountLabel: UILabel!
    @IBOutlet weak var totalAmountLabel: UILabel!

    override func viewDidLoad() {
        super.viewDidLoad()
        tipControl.addTarget(self, action: #selector(calculateTipAndTotal), for: .valueChanged)
    }

    @objc func calculateTipAndTotal() {
        guard let billAmountText = billAmountTextField.text, let billAmount = Double(billAmountText) else {
            return
        }

        let tipPercentages = [0.15, 0.20, 0.25]
        let selectedTipPercentage = tipPercentages[tipControl.selectedSegmentIndex]

        let tipAmount = billAmount * selectedTipPercentage
        let totalAmount = billAmount + tipAmount

        tipAmountLabel.text = String(format: "$%.2f", tipAmount)
        totalAmountLabel.text = String(format: "$%.2f", totalAmount)
    }
}
