### Solution:
```go
package main

import (
	"fmt"
	"os"
	"os/exec"
	"runtime"
	"time"

	"github.com/eiannone/keyboard"
)

type point struct {
	x, y int
}

type snakeGame struct {
	width, height int
	snake         []point
	fps           int
	direction     string
}

func (g *snakeGame) init() {
	g.width, g.height = getTerminalSize()
	g.snake = []point{{g.width / 2, g.height / 2}}
	g.fps = 8
	g.direction = "right"
}

func (g *snakeGame) update() {
	g.clearScreen()
	g.handleInput()
	g.moveSnake()
	g.render()
	time.Sleep(time.Second / time.Duration(g.fps))
}

func (g *snakeGame) handleInput() {
	if runtime.GOOS == "windows" {
		if keyboard.IsKeyDown(0x57) {
			g.direction = "up"
		} else if keyboard.IsKeyDown(0x53) {
			g.direction = "down"
		} else if keyboard.IsKeyDown(0x41) {
			g.direction = "left"
		} else if keyboard.IsKeyDown(0x44) {
			g.direction = "right"
		}
	} else {
		char, key, err := keyboard.GetSingleKey()
		if err != nil {
			panic(err)
		}
		switch key {
		case keyboard.KeyArrowUp:
			g.direction = "up"
		case keyboard.KeyArrowDown:
			g.direction = "down"
		case keyboard.KeyArrowLeft:
			g.direction = "left"
		case keyboard.KeyArrowRight:
			g.direction = "right"
		}
	}
}

func (g *snakeGame) moveSnake() {
	head := g.snake[0]
	var newHead point
	switch g.direction {
	case "up":
		newHead = point{head.x, head.y - 1}
	case "down":
		newHead = point{head.x, head.y + 1}
	case "left":
		newHead = point{head.x - 1, head.y}
	case "right":
		newHead = point{head.x + 1, head.y}
	}
	g.snake = append([]point{newHead}, g.snake...)
	g.snake = g.snake[:len(g.snake)-1]
}

func (g *snakeGame) render() {
