	for y := 0; y < g.height; y++ {
		for x := 0; x < g.width; x++ {
			if x == g.snake[0].x && y == g.snake[0].y {
				fmt.Print("O")
			} else {
				fmt.Print(" ")
			}
		}
		fmt.Println()
	}
}

func (g *snakeGame) clearScreen() {
	cmd := exec.Command("clear")
	if runtime.GOOS == "windows" {
		cmd = exec.Command("cmd", "/c", "cls")
	}
	cmd.Stdout = os.Stdout
	cmd.Run()
}

func getTerminalSize() (int, int) {
	cmd := exec.Command("stty", "size")
	cmd.Stdin = os.Stdin
	out, _ := cmd.Output()
	var rows, cols int
	fmt.Sscanf(string(out), "%d %d", &rows, &cols)
	return cols, rows
}

func main() {
	game := snakeGame{}
	game.init()
	defer keyboard.Close()
	for {
		game.update()
	}
}
```

