import Foundation

func parsePackageSwift(fileContent: String) -> [(name: String, path: String)] {
    var targets: [(name: String, path: String)] = []

    let targetPattern = #"\.target\(name: "(.*?)", path: "(.*?)""#
    let regex = try! NSRegularExpression(pattern: targetPattern, options: [])

    let matches = regex.matches(in: fileContent, options: [], range: NSRange(location: 0, length: fileContent.utf16.count))

    for match in matches {
        if let nameRange = Range(match.range(at: 1), in: fileContent),
           let pathRange = Range(match.range(at: 2), in: fileContent) {
            let name = String(fileContent[nameRange])
            let path = String(fileContent[pathRange])
            targets.append((name: name, path: path))
        }
    }

    return targets
}

// Example usage
let packageSwiftContent = """
    targets: [
        .target(
            name: "MimeLib",
            path: "Sources"
         ),
    ],
"""
let extractedTargets = parsePackageSwift(fileContent: packageSwiftContent)
for target in extractedTargets {
    print("Target Name: \(target.name), Path: \(target.path)")
}
```

The `parsePackageSwift` function uses regular expressions to extract the target names and paths from the given Package.swift file content. It then returns a list of tuples containing the extracted target names and paths. The example usage demonstrates how to use the function with the provided Package.swift file snippet and print the extracted information.

