  "@/app/contexts/AppContext": 1,
  "@/app/isClientSide": 1,
  "@/app/components/SEOMetaTags": 1,
  "@/app/components/AppInitializer": 1,
  "./globals.css": 1
}
```

Note:
In the given code snippet, the function should identify the imported modules and their import counts. The `import` statements are in ES6 syntax, and the module names are enclosed in curly braces `{}`.

### Solution:
```javascript
function extractImportedModules(code) {
  const importRegex = /import\s*{([^}]*)}\s*from\s*['"]([^'"]*)['"]/g;
  let match;
  const importedModules = {};

  while ((match = importRegex.exec(code)) !== null) {
    const importedItems = match[1].split(',').map(item => item.trim());
    const modulePath = match[2];

    importedItems.forEach(item => {
      const moduleName = item.split(' as ')[0].trim();
      importedModules[modulePath] = (importedModules[modulePath] || 0) + 1;
    });
  }

  return importedModules;
}

