### Solution:
```typescript
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Record } from './record.entity';

@Injectable()
export class RecordsService {
  constructor(
    @InjectRepository(Record)
    private readonly recordRepository: Repository<Record>,
  ) {}

  async addRecord(record: Record): Promise<Record> {
    return await this.recordRepository.save(record);
  }

  async getRecordById(id: number): Promise<Record | undefined> {
    return await this.recordRepository.findOne(id);
  }

  async updateRecord(id: number, updatedData: Partial<Record>): Promise<Record | undefined> {
    const record = await this.recordRepository.findOne(id);
    if (record) {
      await this.recordRepository.merge(record, updatedData);
      return await this.recordRepository.save(record);
    }
    return undefined;
  }

  async deleteRecord(id: number): Promise<boolean> {
    const result = await this.recordRepository.delete(id);
    return result.affected > 0;
  }
}
```

In the solution, the `RecordsService` class is implemented with methods to add, retrieve, update, and delete records using TypeORM. The `@InjectRepository` decorator is used to inject the `Record` repository, and the methods perform the corresponding database operations.

