// Define the appReducers
const initialState = {
  count: 0
};

const appReducers = (state = initialState, action) => {
  switch (action.type) {
    case "INCREMENT":
      return { ...state, count: state.count + 1 };
    case "DECREMENT":
      return { ...state, count: state.count - 1 };
    default:
      return state;
  }
};

// Configure the Redux store
import { createStore, applyMiddleware } from "redux";
import { createLogger } from "redux-logger";

const rootReducer = combineReducers({
  app: appReducers
});

const loggerMiddleware = createLogger();

const store = createStore(rootReducer, applyMiddleware(loggerMiddleware));

// Test the Redux store
store.dispatch({ type: "INCREMENT" });
console.log(store.getState()); // Output: { app: { count: 1 } }

store.dispatch({ type: "DECREMENT" });
console.log(store.getState()); // Output: { app: { count: 0 } }
```

In this solution, we define the `appReducers` to handle the state for a simple counter feature. We then configure the Redux store using `createStore` from Redux, combining the reducers with `combineReducers`, and applying middleware for logging actions and state changes using `redux-logger`. Finally, we test the Redux store by dispatching actions and logging the state changes.

