        for key, value in config_data.items():
            label = QLabel(key)
            if isinstance(value, dict):
                sub_widget = QConfigWidget()
                sub_widget.load_config(json.dumps(value))
                self.layout.addWidget(label)
                self.layout.addWidget(sub_widget)
                self.config_widgets[key] = sub_widget
            else:
                line_edit = QLineEdit(str(value))
                self.layout.addWidget(label)
                self.layout.addWidget(line_edit)
                self.config_widgets[key] = line_edit

    def get_config(self) -> str:
        config_data = {}
        for key, widget in self.config_widgets.items():
            if isinstance(widget, QConfigWidget):
                config_data[key] = json.loads(widget.get_config())
            else:
                config_data[key] = widget.text()
        return json.dumps(config_data)

    def clear_config(self):
        for widget in self.config_widgets.values():
            widget.setParent(None)
        self.config_widgets = {}
```

