import { DEFAULT_FORMATS, DEFAULT_INPUT, DEFAULT_SUPPORT } from '../../constants';
import { PackemonPackageConfig, Platform, Support } from '../../types';
import { getVersionsCombo } from '../Environment';

interface PackageFormProps {
  onSubmit: (config: PackemonPackageConfig) => void;
}

function getSupportVersions(platforms: Platform[], support: Support): string {
  return applyStyle([...getVersionsCombo(platforms, support)].sort().join(', '), 'muted');
}

const PackageForm: React.FC<PackageFormProps> = ({ onSubmit }) => {
  const [format, setFormat] = useState<Format>(DEFAULT_FORMATS[0]);
  const [input, setInput] = useState<string>(DEFAULT_INPUT);
  const [platforms, setPlatforms] = useState<Platform[]>([]);
  const [support, setSupport] = useState<Support>(DEFAULT_SUPPORT);

  const handleFormSubmit = useCallback(() => {
    const config: PackemonPackageConfig = { format, input, platforms, support };
    onSubmit(config);
  }, [format, input, platforms, support, onSubmit]);

  return (
    <form onSubmit={handleFormSubmit}>
      <Input value={input} onChange={(e) => setInput(e.target.value)} />
      <Select value={format} options={DEFAULT_FORMATS} onChange={(e) => setFormat(e.target.value as Format)} />
      <MultiSelect value={platforms} options={Object.values(Platform)} onChange={(selected) => setPlatforms(selected)} />
      <div>
        <input type="radio" id="node" name="support" value="node" checked={support === 'node'} onChange={() => setSupport('node')} />
        <label htmlFor="node">Node</label>
        <input type="radio" id="browser" name="support" value="browser" checked={support === 'browser'} onChange={() => setSupport('browser')} />
        <label htmlFor="browser">Browser</label>
        <input type="radio" id="both" name="support" value="both" checked={support === 'both'} onChange={() => setSupport('both')} />
        <label htmlFor="both">Both</label>
      </div>
      <button type="submit">Submit</button>
    </form>
  );
};

export default PackageForm;
```

