import java.util.regex.Pattern;

public class DateTimeExtractor {
    public static String extractDateTime(String codeSnippet) {
        String pattern = ".*@date (\\d{4})年(\\d{1,2})月(\\d{1,2})日 下午(\\d{1,2}):(\\d{1,2}):(\\d{1,2}).*";
        Pattern r = Pattern.compile(pattern);
        Matcher m = r.matcher(codeSnippet);

        if (m.find()) {
            String year = m.group(1);
            String month = m.group(2);
            String day = m.group(3);
            String hour = m.group(4);
            String minute = m.group(5);
            String second = m.group(6);

            return String.format("%s-%02d-%02d %02d:%02d:%02d", year, Integer.parseInt(month), Integer.parseInt(day),
                    Integer.parseInt(hour), Integer.parseInt(minute), Integer.parseInt(second));
        } else {
            return "No date and time information found in the code snippet.";
        }
    }

    public static void main(String[] args) {
        String codeSnippet = " * @date 2017年6月28日 下午8:06:53\n*\n*/\npackage com.tangkuo.cn.main;";
        String extractedDateTime = extractDateTime(codeSnippet);
        System.out.println(extractedDateTime); // Output: 2017-06-28 20:06:53
    }
}
```

