import luigi
import os
import time

NSDE_RAW_DIR = '/path/to/your/raw/directory'

def newest_file_timestamp(directory):
    files = [os.path.join(directory, f) for f in os.listdir(directory) if os.path.isfile(os.path.join(directory, f))]
