                print(f"File '{command[1]}' created successfully")
            except FileExistsError as e:
                print(e)
        elif command[0] == "delete" and len(command) == 2:
            try:
                file_manager.delete_file(command[1])
                print(f"File '{command[1]}' deleted successfully")
            except FileNotFoundError as e:
                print(e)
        elif command[0] == "list" and len(command) == 1:
            files = file_manager.list_files()
            if files:
                print("Files in directory:")
                for file in files:
                    print(file)
            else:
                print("No files in directory")
        else:
            print("Invalid command format")
